    use super::*;

    #[test]
    fn only_the_requester_signs_off_a_uat_script() {
        assert!(signs_off(Stage::Uat, "ada", "ada").is_ok());
        let refused = signs_off(Stage::Uat, "ada", "root").unwrap_err();
