    State(app): State<App>,
    Path(id): Path<String>,
    Json(w): Json<bastion_protocol::WorkflowView>,
) -> Response {
    let saved = api::workflows::workflow_save(&app.server.factory, id, w).await;
    if saved.is_ok() {
        app.server.events.publish(Change::Job { id: String::new() });
    }
    answer(saved)
}
