            .call(NS, "secrets::access", access(with))
            .await?;
        let resolved = self
            .engine
            .call(
                NS,
                "secrets::resolve",
                json!({ "ref": format!("secret://{name}") }),
            )
            .unwrap()
    }

    #[test]
    fn a_spawned_program_gets_the_basics_and_no_secrets() {
        for kept in ["PATH", "HOME", "TMPDIR", "III_URL"] {
            assert!(passed(kept), "{kept}");
        }
        for dropped in [
            "GITHUB_TOKEN",
            "OPENAI_API_KEY",
            "NPM_TOKEN",
            "AWS_SECRET_ACCESS_KEY",
        ] {
            assert!(!passed(dropped), "{dropped}");
